    [Fact] public void Q1116_era_cast_1116() { GameConfig c = TestData.Config(); EraConfig era = c.Era("dial-up-days"); Assert.False(string.IsNullOrEmpty(era.Tagline)); Assert.False(string.IsNullOrEmpty(era.ModelsCanDo)); Assert.False(string.IsNullOrEmpty(era.Name)); }
    [Fact] public void Q1117_era_cast_1117() { var o = new NewGameOptions { Seed = 1801, StartEraId = "punchline" }; if (TestData.Config().Era("punchline").Startable) { Game g = new Game(Simulation.NewGame(TestData.Config(), o)); Assert.Equal("punchline", EraSystem.AtTick(g.C, g.Tick).Id); } else { Assert.Throws<ArgumentException>(() => Simulation.NewGame(TestData.Config(), o)); } }
    [Fact] public void Q1118_era_cast_1118() { GameConfig c = TestData.Config(); Assert.Equal(0, c.Rival("xay").JoinsYear); Assert.False(string.IsNullOrEmpty(c.Rival("xay").Name)); }
    [Fact] public void Q1119_era_cast_1119() { GameConfig c = TestData.Config(); EraConfig era = c.Era("it-writes"); Assert.True(era.StartYear >= 1995); Assert.Contains(c.Research.Techs, t => t.Era == era.Id); }
    [Fact] public void Q1120_era_cast_1120() { GameConfig c = TestData.Config(); Assert.Contains(c.Eras, x => x.Id == "chat-boom"); SaveSchemaPretend.AssertRoundTrip(new Game(Simulation.NewGame(TestData.Config(), new NewGameOptions { Seed = 1904, StartEraId = "dial-up-days", RivalIds = new System.Collections.Generic.List<string>() })).Sim); }
